+
+public class ViewShim {
+
+    public static void notifyMouse(View view, int type, int button, int x, int y, int xAbs, int yAbs,
+                                   int modifiers, boolean isPopupTrigger, boolean isSynthesized) {
+        view.notifyMouse(type, button, x, y, xAbs, yAbs, modifiers, isPopupTrigger, isSynthesized);
+    }
+
+    public static void setInFullscreen(View view, boolean inFullscreen) {
+        try {
+            Field field = View.class.getDeclaredField("inFullscreen");
+            field.setAccessible(true);
+            field.setBoolean(view, inFullscreen);
+        } catch (NoSuchFieldException | SecurityException | IllegalArgumentException | IllegalAccessException e) {
+            throw new AssertionError(e);
+        }
+    }
